const API_BASE = import.meta.env.VITE_API_BASE || 'http://localhost:5000';
const TOKEN_KEY = 'hcm_lite_token';
const MONEY = value => `PKR ${Number(value || 0).toLocaleString('en-PK', { maximumFractionDigits: 0 })}`;
const DATE_TODAY = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const toDate = value => value ? String(value).slice(0, 10) : '';
const id = obj => String(obj?._id ?? obj?.id ?? '');
const initials = value => String(value || '?').split(/\s+/).slice(0, 2).map(s => s[0] || '').join('').toUpperCase();
const titleCase = value => String(value || '').replaceAll('_', ' ').replace(/\b\w/g, c => c.toUpperCase());
const attendanceLabel = value => ({ present:'Present', late:'Late', half_day:'Half day', missing_checkout:'Missing checkout', absent:'Absent', on_leave:'On leave', not_due:'Not due' }[value] || titleCase(value));
const leaveTypes = ['Annual', 'Sick', 'Casual', 'Unpaid'];

async function api(path, options = {}) {
  const headers = { ...(options.headers || {}) };
  const token = localStorage.getItem(TOKEN_KEY);
  if (token) headers.Authorization = `Bearer ${token}`;
  let body = options.body;
  if (body !== undefined && !(body instanceof FormData) && !(body instanceof Blob) && typeof body !== 'string') {
    headers['Content-Type'] = 'application/json'; body = JSON.stringify(body);
  }
  const response = await fetch(`${API_BASE}${path}`, { ...options, headers, body });
  if (!response.ok) {
    let message = `${response.status} ${response.statusText}`;
    try { const payload = await response.json(); message = payload.message || message; } catch {}
    const error = new Error(message); error.status = response.status;
    if (response.status === 401) { localStorage.removeItem(TOKEN_KEY); }
    throw error;
  }
  const contentType = response.headers.get('content-type') || '';
  return contentType.includes('application/pdf') || contentType.includes('text/csv') ? response.blob() : response.json();
}

